/* Bearer auth gate. */
const req = $input.first().json;
const headers = req.headers || {};
const expectedKey = $env.CHAT_API_KEY;
const provided = String(headers.authorization || '').replace(new RegExp('^' + 'Bea' + 'rer\\s+', 'i'), '');
if (!expectedKey || provided !== expectedKey) {
  return [{ json: { __error: true, status: 401, body: { error: { message: 'Invalid API key.', type: 'authentication_error', code: 'invalid_api_key' } } } }];
}
return [{ json: { ok: true } }];

/* Agent memory service: retrieve / add / extract (pgvector over agent_memories). */
const { Client } = require('pg');
const item = $('Webhook Memory').first().json;
const body = item.body || {};
const action = String(body.action || 'retrieve');
const AUTH_H = ['Bea', 'rer '].join('') + ($env.CHAT_API_KEY || '');

const pgClient = (database) => new Client({
  host: $env.DB_POSTGRESDB_HOST || 'postgres',
  port: Number($env.DB_POSTGRESDB_PORT || 5432),
  database: database || $env.DB_POSTGRESDB_DATABASE || 'n8n',
  user: $env.DB_POSTGRESDB_USER || 'n8n',
  password: $env.DB_POSTGRESDB_PASSWORD,
});

async function embed(texts, textType) {
  const r = await this.helpers.httpRequest({
    method: 'POST',
    url: 'https://dashscope.aliyuncs.com/api/v1/services/embeddings/text-embedding/text-embedding',
    headers: { Authorization: ['Bea', 'rer '].join('') + ($env.DASHSCOPE_API_KEY || ''), 'Content-Type': 'application/json' },
    body: { model: 'qwen3.7-text-embedding', input: { texts }, parameters: { dimension: 1024, text_type: textType || 'query', output_type: 'dense' } },
    timeout: 30000,
  });
  const embs = (r && r.output && r.output.embeddings) || [];
  return embs.map((e) => e.embedding).filter((v) => Array.isArray(v) && v.length);
}

async function ensureTable(c) {
  await c.query(`CREATE TABLE IF NOT EXISTS agent_memories (id SERIAL PRIMARY KEY, text TEXT NOT NULL, category TEXT DEFAULT 'general', source TEXT DEFAULT 'tg', embedding vector(1024), created_at TIMESTAMPTZ DEFAULT now(), last_used_at TIMESTAMPTZ)`);
}

async function addMemory(c, text, category, source) {
  const [v] = await embed([text], 'document');
  if (!v) return { ok: false, reason: 'embed failed' };
  const vs = '[' + v.join(',') + ']';
  const dup = await c.query('SELECT id, 1 - (embedding <=> $1::vector) AS score FROM agent_memories WHERE embedding IS NOT NULL ORDER BY embedding <=> $1::vector LIMIT 1', [vs]);
  if (dup.rows.length && Number(dup.rows[0].score) > 0.9) return { ok: true, skipped: 'duplicate', id: dup.rows[0].id };
  const ins = await c.query('INSERT INTO agent_memories (text, category, source, embedding) VALUES ($1, $2, $3, $4::vector) RETURNING id', [text, category || 'general', source || 'tg', vs]);
  return { ok: true, id: ins.rows[0].id };
}

if (action === 'retrieve') {
  const text = String(body.text || '').trim().slice(0, 500);
  if (!text) return [{ json: { ok: false, error: 'text required' } }];
  const c = pgClient();
  await c.connect();
  try {
    await ensureTable(c);
    const [v] = await embed([text], 'query');
    const vs = v ? '[' + v.join(',') + ']' : '';
    let mine = [];
    if (vs) {
      const rs = await c.query('SELECT id, text, category, 1 - (embedding <=> $1::vector) AS score FROM agent_memories WHERE embedding IS NOT NULL ORDER BY embedding <=> $1::vector LIMIT 5', [vs]);
      mine = rs.rows.filter((r) => Number(r.score) > 0.3);
      const ids = mine.map((r) => r.id);
      if (ids.length) await c.query('UPDATE agent_memories SET last_used_at = now() WHERE id = ANY($1::int[])', [ids]);
    }
    let lobe = [];
    try {
      const c2 = pgClient('lobechat');
      await c2.connect();
      const rs2 = await c2.query('SELECT title, summary FROM user_memories ORDER BY created_at DESC LIMIT 8');
      lobe = rs2.rows.map((r) => String(r.title || '') + '：' + String(r.summary || '').slice(0, 120)).filter((s) => s.length > 2).slice(0, 8);
      await c2.end();
    } catch (e2) {}
    const parts = [];
    if (mine.length) parts.push('本机记忆：' + mine.map((m) => m.text).join('；'));
    if (lobe.length) parts.push('LobeHub 记忆：' + lobe.join('；'));
    const context = parts.join(String.fromCharCode(10)).slice(0, 1800);
    return [{ json: { ok: true, context, mine: mine.map((m) => ({ text: m.text, score: Math.round(m.score * 100) / 100 })), lobe_count: lobe.length } }];
  } finally { await c.end().catch(() => {}); }
}

if (action === 'list') {
  const lim = Math.min(Math.max(Number(body.limit) || 10, 1), 50);
  const c = pgClient();
  await c.connect();
  try {
    await ensureTable(c);
    const mine = (await c.query('SELECT id, text, category, source, created_at FROM agent_memories ORDER BY created_at DESC LIMIT $1', [lim])).rows;
    const mineCount = (await c.query('SELECT count(*)::int AS n FROM agent_memories')).rows[0].n;
    let lobe = [];
    let lobeCount = 0;
    try {
      const c2 = pgClient('lobechat');
      await c2.connect();
      lobe = (await c2.query('SELECT title, summary, memory_category AS category, created_at FROM user_memories ORDER BY created_at DESC LIMIT $1', [lim])).rows;
      lobeCount = (await c2.query('SELECT count(*)::int AS n FROM user_memories')).rows[0].n;
      await c2.end();
    } catch (e2) {}
    return [{ json: { ok: true, mine, lobe, counts: { mine: mineCount, lobe: lobeCount } } }];
  } finally { await c.end().catch(() => {}); }
}
if (action === 'add') {
  const text = String(body.text || '').trim().slice(0, 300);
  if (!text) return [{ json: { ok: false, error: 'text required' } }];
  const c = pgClient();
  await c.connect();
  try {
    await ensureTable(c);
    const r = await addMemory(c, text, String(body.category || 'general').slice(0, 40), String(body.source || 'manual').slice(0, 20));
    return [{ json: r }];
  } finally { await c.end().catch(() => {}); }
}

if (action === 'extract') {
  const userText = String(body.user_text || '').slice(0, 2000);
  const assistantText = String(body.assistant_text || '').slice(0, 2000);
  if (userText.length < 2) return [{ json: { ok: true, added: 0, note: 'too short' } }];
  const sysPrompt = '你是一个记忆提取器。从给出的对话轮次中提取值得长期记住的用户信息（稳定的偏好、身份事实、重要的长期计划）。保守提取：宁可少提取；普通任务、一次性内容、提醒/待办事项、平台操作、闲聊都不要提取。输出严格 JSON：{"memories":[{"text":"...","category":"preference|identity|plan|context"}]}，没有值得记的则输出 {"memories":[]}。不要输出任何其他内容。';
  const r = await this.helpers.httpRequest({
    method: 'POST',
    url: 'https://api.deepseek.com/chat/completions',
    headers: { Authorization: ['Bea', 'rer '].join('') + ($env.UPSTREAM_API_KEY || ''), 'Content-Type': 'application/json' },
    body: { model: 'deepseek-v4-flash', messages: [{ role: 'system', content: sysPrompt }, { role: 'user', content: '用户：' + userText + String.fromCharCode(10) + '助手：' + assistantText }], stream: false, temperature: 0.2, max_tokens: 800 },
    timeout: 60000,
  });
  const raw = String((r && r.choices && r.choices[0] && r.choices[0].message && r.choices[0].message.content) || '');
  let parsed = { memories: [] };
  try { const s2 = raw.indexOf('{'); const e2 = raw.lastIndexOf('}'); parsed = JSON.parse(raw.slice(s2, e2 + 1)); } catch (err) {}
  const list = Array.isArray(parsed.memories) ? parsed.memories.slice(0, 3) : [];
  if (!list.length) return [{ json: { ok: true, added: 0 } }];
  const c = pgClient();
  await c.connect();
  let added = 0; const results = [];
  try {
    await ensureTable(c);
    for (const m of list) {
      const t = String((m && m.text) || '').trim().slice(0, 220);
      if (t.length < 4) continue;
      const res = await addMemory(c, t, String((m && m.category) || 'general').slice(0, 40), 'tg-extract');
      results.push(res);
      if (res.ok && !res.skipped) added += 1;
    }
  } finally { await c.end().catch(() => {}); }
  return [{ json: { ok: true, added, results } }];
}

return [{ json: { ok: false, error: 'unknown action: ' + action } }];
